                                    continue 'recovery_menu;
                                }
                            }
                            RecoveryAction::Shell => {
                                ui.message("    Dropping to debug shell (exit to return)...");
                                crate::shell::debug::spawn_debug_shell(
                                    step_name,
                                    project_root,
                                    &step.env,
                                    global_env,
                                )?;
