770→        let temp = TempDir::new().unwrap();
771→        fs::write(temp.path().join("done.txt"), "").unwrap();
772→
773→        let mut step = make_step("echo should not run");
774→        // completed_check passes → should skip; precondition would fail
775→        step.completed_check = Some(CompletedCheck::FileExists {
776→            path: "done.txt".to_string(),
777→        });
778→        step.precondition = Some(CompletedCheck::CommandSucceeds {
779→            command: "exit 1".to_string(),
780→        });
781→
782→        let ctx = InterpolationContext::new();
783→        let options = ExecutionOptions::default();
784→
785→        let result =
786→            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();
787→
788→        // completed_check causes skip, precondition never evaluated
789→        assert!(result.success);
790→        assert!(result.skipped);
791→    }
