  1→//! Sensitive step handling.
  2→//!
  3→//! This module provides special handling for steps that process sensitive data.
  4→
  5→/// Manages sensitive step execution.
  6→///
  7→/// # Example
  8→///
  9→/// ```
 10→/// use bivvy::steps::SensitiveStepHandler;
 11→///
 12→/// // Configure handler based on execution mode
 13→/// let handler = SensitiveStepHandler::new(false, false);
 14→///
 15→/// // Dry-run hides the actual command
 16→/// let handler_dry = SensitiveStepHandler::new(true, false);
 17→/// let display = handler_dry.dry_run_display("vault read secret/key");
 18→/// assert!(display.contains("SENSITIVE"));
 19→///
 20→/// // Sensitive output is not logged
 21→/// assert!(!handler.should_log_output());
 22→///
 23→/// // In non-interactive mode, no confirmation needed
 24→/// let handler_non_interactive = SensitiveStepHandler::new(false, true);
 25→/// assert!(!handler_non_interactive.should_confirm("fetch-secrets"));
 26→/// ```
 27→pub struct SensitiveStepHandler {
 28→    /// Whether running in dry-run mode.
 29→    is_dry_run: bool,
 30→    /// Whether running in non-interactive mode.
 31→    is_non_interactive: bool,
 32→}
 33→
 34→impl SensitiveStepHandler {
 35→    /// Create a new handler with the given settings.
 36→    pub fn new(is_dry_run: bool, is_non_interactive: bool) -> Self {
 37→        Self {
 38→            is_dry_run,
 39→            is_non_interactive,
 40→        }
 41→    }
 42→
 43→    /// Check if user should confirm before running sensitive step.
 44→    ///
 45→    /// Confirmation is skipped in non-interactive mode or CI.
 46→    pub fn should_confirm(&self, _step_name: &str) -> bool {
 47→        // Don't confirm in non-interactive mode or CI
 48→        if self.is_non_interactive {
 49→            return false;
 50→        }
 51→        if std::env::var("CI").is_ok() {
 52→            return false;
 53→        }
 54→        // Always confirm sensitive steps otherwise
 55→        true
 56→    }
 57→
 58→    /// Get display text for dry-run output.
 59→    ///
 60→    /// The actual command is hidden to prevent exposure in logs.
 61→    pub fn dry_run_display(&self, _command: &str) -> String {
 62→        "[SENSITIVE - command hidden in dry-run]".to_string()
 63→    }
 64→
 65→    /// Check if command output should be logged.
 66→    ///
 67→    /// Sensitive steps suppress output logging to prevent data exposure.
 68→    pub fn should_log_output(&self) -> bool {
 69→        false
 70→    }
 71→
 72→    /// Check if running in dry-run mode.
 73→    pub fn is_dry_run(&self) -> bool {
 74→        self.is_dry_run
 75→    }
 76→
 77→    /// Check if running in non-interactive mode.
 78→    pub fn is_non_interactive(&self) -> bool {
 79→        self.is_non_interactive
 80→    }
 81→}
 82→
 83→impl Default for SensitiveStepHandler {
 84→    fn default() -> Self {
 85→        Self::new(false, false)
 86→    }
 87→}
